const rows = $input.all().map(item => item.json);

if (
  rows.length === 0 ||
  rows.every(r => !r || Object.keys(r).length === 0)
) {
  return [{
    json: {
      found: 'false',
      count: '0',
      summary: 'No open requests are on record for this customer yet.',
      refund_ready: 'false',
      refund_order_id: '',
      refund_return_id: ''
    }
  }];
}

const readyRecords = [];

const lines = rows.map(r => {
  let what = !r.return_id
    ? `Request for order ${r.order_id}`
    : `${r.kind === 'exchange' ? 'Exchange' : 'Return'} ${r.return_id} for the ${r.item} (order ${r.order_id})`;

  let state;

  if (['inspection', 'Exchange'].includes(r.kind)) {
    const passed =
      r.inspection_status === 'passed' ||
      r.return_status === 'inspected';

    const refunded = Number(r.refund_count || 0) > 0;

    if (passed && r.kind === 'exchange') {
      state = 'the item passed inspection and the new item is approved and being dispatched';

    } else if (passed && refunded) {
      state = 'the item passed inspection and the refund has been started';

    } else if (passed) {
      readyRecords.push(r);
      state = 'the item has PASSED inspection and the refund can be started now';

    } else if (
      r.inspection_status === 'failed' ||
      r.return_status === 'rejected'
    ) {
      const note = r.inspection_note
        ? ` (${r.inspection_note})`
        : '';

      state = `the item did not pass inspection${note}, so no refund or exchange goes ahead`;

    } else {
      state = 'waiting for our team to inspect the item once it reaches us';
    }

  } else {
    what = `Your ${r.kind === 'case' ? 'request' : 'escalation'} for order ${r.order_id}`;

    switch ((r.last_status || '').toLowerCase()) {
      case 'closed':
      case 'done':
      case 'resolved':
        state = 'resolved by our team';
        break;

      case 'in progress':
      case 'working':
      case 'escalated':
        state = 'being worked on by our team';
        break;

      default:
        state = 'received and queued with our team';
    }
  }

  return `${what}: ${state} (last update ${r.updated})`;
});

return [{
  json: {
    found: 'true',
    count: rows.length.toString(),
    summary: lines.join('\n'),
    refund_ready: readyRecords.length > 0 ? 'true' : 'false',
    refund_order_id: rows.map(r => r.order_id || '').join(','),
    refund_return_id: rows.map(r => r.return_id || '').join(',')
  }
}];

